typedef enum
{
    //! To access CPU1 Memory
    DCSM_CPUSEL_CPU1 = 0x0U,
    //! To access CPU2 Memory
    DCSM_CPUSEL_CPU2 = 0x2U,
    //! To access CM Memory
    DCSM_CPUSEL_CM = 0x1U

} DCSM_CPUSel;

//*****************************************************************************
//
//! The following are values that can be passed to
