typedef enum
{
    IPC_CPU1_L_CPU2_R,       //!< CPU1 - Local core, CPU2 - Remote core
    IPC_CPU1_L_CM_R,         //!< CPU1 - Local core, CM   - Remote core
    IPC_CPU2_L_CPU1_R,       //!< CPU2 - Local core, CPU1 - Remote core
    IPC_CPU2_L_CM_R,         //!< CPU2 - Local core, CM   - Remote core
    IPC_TOTAL_NUM
}IPC_Type_t;

