    // Sets the Rx frame tag mask.
    //
    HWREGH(base + FSI_O_RX_FRAME_TAG_CMP) =
          ((HWREGH(base + FSI_O_RX_FRAME_TAG_CMP) &
           ~((uint16_t)FSI_RX_FRAME_TAG_CMP_TAG_MASK_M)) |
           (maskVal << FSI_RX_FRAME_TAG_CMP_TAG_MASK_S));
